grammar node.Matrix with parent.One, parent.Two hidden(WS)
generate g 'urn:generated' as gen
import 'urn:external' as ext
@Override @Deprecated Rule<P,Q> returns gen::Model hidden(WS,COMMENT):
 <P | Q & !false> name=ID
 | (a?='a' & b+='b'?)
 | {gen::Model} 'x' {gen::Model.items+=current}
 | =>('left' Other<flag=P,true>)
 | ->name=(ID | 'keyword')
 | ref=[gen::Model|'fixed'];
fragment Any *: 'any';
terminal fragment Frag: ('a'..'z')+;
terminal TOKEN returns ext::EString: Frag !('a'|'b') ->('x'|'y') . EOF;
enum Choice returns gen::Choice: One='one' | Two;
